import{_ as a,o as s,c as i,a5 as r}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"内存模型与函数调用","description":"在进入汇编之前，先用 C 语言的视角理解两件事：程序的内存分几块、函数调用时发生了什么。这两个概念是后面读汇编、看栈帧的共同基础。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"reverse-engineering/01-program-basics/chapter-02-memory-function-call.md","filePath":"reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"}'),n={name:"reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"};function t(l,e,c,p,d,o){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="内存模型与函数调用" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">内存模型与函数调用 <a class="header-anchor" href="#内存模型与函数调用" aria-label="Permalink to &quot;内存模型与函数调用&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">在进入汇编之前，先用 C 语言的视角理解两件事：程序的内存分几块、函数调用时发生了什么。这两个概念是后面读汇编、看栈帧的共同基础。</p><h2 id="_1-程序的内存分几块" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">1. 程序的内存分几块 <a class="header-anchor" href="#_1-程序的内存分几块" aria-label="Permalink to &quot;1. 程序的内存分几块&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">一个运行中的程序，其内存大致分为几块：</p><table tabindex="0"><thead data-src-line="10" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><tr data-src-line="10" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><th style="text-align:left;">区域</th><th style="text-align:left;">存什么</th><th style="text-align:left;">生命周期</th></tr></thead><tbody data-src-line="12" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><tr data-src-line="12" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><td style="text-align:left;">代码段（.text）</td><td style="text-align:left;">编译后的机器码</td><td style="text-align:left;">整个程序运行期间</td></tr><tr data-src-line="13" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><td style="text-align:left;">数据段（.data / .rdata）</td><td style="text-align:left;">全局变量、静态变量、常量</td><td style="text-align:left;">整个程序运行期间</td></tr><tr data-src-line="14" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><td style="text-align:left;">堆（heap）</td><td style="text-align:left;">动态分配的内存（<code>malloc</code>/<code>new</code>）</td><td style="text-align:left;">手动分配、手动释放</td></tr><tr data-src-line="15" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><td style="text-align:left;">栈（stack）</td><td style="text-align:left;">局部变量、函数调用信息</td><td style="text-align:left;">函数调用期间</td></tr></tbody></table><p data-src-line="17" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">其中<strong>栈</strong>和<strong>堆</strong>是逆向里反复出现的两个概念，必须分清：</p><ul data-src-line="19" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><li data-src-line="19" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><strong>栈</strong>：由编译器自动管理，函数调用时分配、返回时释放。速度快，但容量有限，只能存局部变量和调用信息。</li><li data-src-line="20" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><strong>堆</strong>：由程序显式管理，灵活但需要手动释放，分配和释放的时机由程序逻辑决定。</li></ul><p data-src-line="22" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">在反汇编里，栈上的变量通过 <code>[rsp + 偏移]</code> 访问，堆上的对象通过指针（寄存器里存地址）访问。</p><h2 id="_2-指针-内存的地址" tabindex="-1" data-src-line="24" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">2. 指针：内存的地址 <a class="header-anchor" href="#_2-指针-内存的地址" aria-label="Permalink to &quot;2. 指针：内存的地址&quot;">​</a></h2><p data-src-line="26" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">指针是 C 语言里最核心、也是逆向里最需要理解的概念。一个指针就是一个<strong>内存地址</strong>，它指向内存里某个位置的数据。</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // x 在栈上，值是 42</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     // p 存的是 x 的地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // 通过地址改 x 的值</span></span></code></pre></div><p data-src-line="34" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">在反汇编里，指针表现为「寄存器里存着一个地址，然后 <code>[寄存器]</code> 去读那个地址的内容」。看到 <code>mov rax, [rcx]</code>，就是在解引用一个指针：<code>rcx</code> 是地址，<code>[rcx]</code> 是那个地址处的内容。</p><p data-src-line="36" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">理解指针是读反汇编的前提：<strong>反汇编里的方括号 <code>[...]</code> 就是指针解引用</strong>。</p><h2 id="_3-函数调用-栈帧的建立与销毁" tabindex="-1" data-src-line="38" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">3. 函数调用：栈帧的建立与销毁 <a class="header-anchor" href="#_3-函数调用-栈帧的建立与销毁" aria-label="Permalink to &quot;3. 函数调用：栈帧的建立与销毁&quot;">​</a></h2><p data-src-line="40" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">调用一个函数时，程序要在栈上做一套「建立 → 使用 → 销毁」的动作，这套动作用到的栈区域叫<strong>栈帧（stack frame）</strong>：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // sum 是局部变量，存在栈帧里</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sum;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p data-src-line="49" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">调用 <code>add(3, 5)</code> 时，栈上大致发生：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调用前：把参数 3、5 准备好（放寄存器或压栈）</span></span>
<span class="line"><span>调用时：保存返回地址（函数返回后回到哪）</span></span>
<span class="line"><span>进入函数：建立栈帧，给局部变量 sum 留空间</span></span>
<span class="line"><span>函数体：在栈帧里读写 sum</span></span>
<span class="line"><span>返回时：销毁栈帧，按返回地址跳回调用处</span></span></code></pre></div><p data-src-line="59" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">这个过程在汇编层面的细节（哪些寄存器、怎么对齐），在<a href="./../02-assembly/chapter-02-x64-assembly.html">x64 汇编</a>里讲。这里先建立 C 语言层面的心智模型：<strong>函数调用 = 参数 + 返回地址 + 局部变量 + 返回</strong>。</p><h2 id="_4-参数传递与返回值" tabindex="-1" data-src-line="61" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">4. 参数传递与返回值 <a class="header-anchor" href="#_4-参数传递与返回值" aria-label="Permalink to &quot;4. 参数传递与返回值&quot;">​</a></h2><p data-src-line="63" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">函数调用涉及两件事：参数怎么传进去，返回值怎么传出来。</p><ul data-src-line="65" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><li data-src-line="65" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><strong>参数</strong>：调用者把参数放到约定的位置（x64 上通常是寄存器，多了才压栈）。</li><li data-src-line="66" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><strong>返回值</strong>：被调函数把结果放到约定的位置（x64 上通常是 <code>RAX</code>）。</li></ul><p data-src-line="68" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">不同的「约定」就是调用约定（calling convention）。C 语言层面你不需要关心细节，但逆向时，<strong>看懂一个函数怎么收参数、怎么返回值，是理解函数功能的第一步</strong>。</p><h2 id="_5-为什么要先建立这些心智模型" tabindex="-1" data-src-line="70" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">5. 为什么要先建立这些心智模型 <a class="header-anchor" href="#_5-为什么要先建立这些心智模型" aria-label="Permalink to &quot;5. 为什么要先建立这些心智模型&quot;">​</a></h2><p data-src-line="72" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">这些 C 语言层面的概念，是读汇编的「预训练」：</p><ul data-src-line="74" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><li data-src-line="74" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">看到栈上的读写 → 对应「局部变量」。</li><li data-src-line="75" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">看到指针解引用 → 对应「访问某块内存」。</li><li data-src-line="76" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">看到函数调用序列 → 对应「参数 + 返回」。</li></ul><p data-src-line="78" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">有了这些心智模型，读汇编时你就不是在看「一堆寄存器操作」，而是在看「一个 C 函数被翻译成了什么」。</p><hr><blockquote data-src-line="82" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md"><p data-src-line="82" data-src-file="reverse-engineering/01-program-basics/chapter-02-memory-function-call.md">本章建立的是 C 语言层面的内存与调用图景：栈和堆是两类内存，指针是地址，函数调用建立和销毁栈帧。下一阶段进入机器码本身——<a href="./../02-assembly/chapter-01-x86-assembly.html">x86 汇编</a>。</p></blockquote>`,29)])])}const m=a(n,[["render",t]]);export{g as __pageData,m as default};
